def findWinningPlayer(skills, k):
    n = len(skills)
    # If k ≥ n-1, the strongest player will eventually win.
    if k >= n - 1:
        return skills.index(max(skills))

    cur_index = 0
    win_count = 0

    for i in range(1, n):
        if skills[cur_index] > skills[i]:
            win_count += 1
        else:
            cur_index = i
            win_count = 1
        if win_count == k:
            return cur_index
    # If never found (shouldn't happen), return cur_index
    return cur_index
